"""Client address resolution (docs/ratelimit.md, section 7)."""

import ipaddress


def parse_addr(text):
    """An ip address object (IPv4-mapped turned into IPv4), or None."""
    if not isinstance(text, str) or "%" in text:
        return None
    try:
        if text.startswith("["):
            end = text.find("]")
            if end < 0:
                return None
            rest = text[end + 1:]
            if rest and not (rest[0] == ":" and rest[1:].isascii() and rest[1:].isdigit()):
                return None
            a = ipaddress.IPv6Address(text[1:end])
        elif text.count(":") == 1:
            host, _, port = text.partition(":")
            if not (port.isascii() and port.isdigit()):
                return None
            a = ipaddress.IPv4Address(host)
        else:
            a = ipaddress.ip_address(text)
    except ValueError:
        return None
    if a.version == 6 and a.ipv4_mapped is not None:
        return a.ipv4_mapped
    return a


def in_any(addr, nets) -> bool:
    return any(addr.version == n.version and addr in n for n in nets)


def client_address(request, trusted):
    """The client address as an ip address object, or the raw peer string when it is no address."""
    peer = parse_addr(request.peer)
    if peer is None:
        return request.peer
    if not in_any(peer, trusted):
        return peer
    entries = []
    for v in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in v.split(","))
    if not entries:
        return peer
    right = peer
    for e in reversed(entries):
        a = parse_addr(e)
        if a is None:
            return right
        if not in_any(a, trusted):
            return a
        right = a
    return parse_addr(entries[0])


def key_text(addr) -> str:
    if isinstance(addr, str):
        return addr
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
