"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.addr import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit") or []
        self.trusted = config.section("clients") or ()
        self.buckets = [{} for _ in self.limits]
        self.limited = {l.name: 0 for l in self.limits}
        self.now = None


def setup(config):
    return State(config)


def _key(limit, ctx, client):
    out = []
    for part in limit.key:
        if part == "tenant":
            v = ctx.tenant
        elif part == "client":
            v = key_text(client)
        elif part == "route":
            v = ctx.route.name
        elif part == "method":
            v = ctx.request.method.upper()
        else:
            v = ctx.request.headers.get(part[len("header:"):])
            v = v.strip(" \t") if v is not None else None
        if v is None or v == "":
            return None
        out.append(v)
    return tuple(out)


def handle(ctx, st):
    if not st.limits:
        return None
    ts = ctx.request.ts_ms
    st.now = ts if st.now is None else max(st.now, ts)
    now = st.now
    method = ctx.request.method.upper()
    client = client_address(ctx.request, st.trusted)
    cov = []
    for i, lim in enumerate(st.limits):
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and method not in lim.methods:
            continue
        if not isinstance(client, str) and in_any(client, lim.exempt):
            continue
        key = _key(lim, ctx, client)
        if key is None:
            continue
        s = st.buckets[i].get(key)
        if s is None:
            s = st.buckets[i][key] = new_state(lim, now)
        s.refill(now)
        cov.append((i, lim, s, lim.cost_of(method)))
    if not cov:
        return None
    refusing = [(i, lim, s, c) for i, lim, s, c in cov if not s.allows(c)]
    if not refusing:
        for _, _, s, c in cov:
            s.charge(c)
        best = min(cov, key=lambda t: (t[2].remaining(), t[0]))
        _, lim, s, _ = best
        ctx.headers.update(_headers(lim, s, now))
        return None
    best = None
    for i, lim, s, c in refusing:
        st.limited[lim.name] += 1
        over = c > lim.capacity
        w = Fraction(0) if over else s.wait(c, now)
        rank = (1, 0) if over else (0, w)
        if best is None or rank > best[0]:
            best = (rank, lim, s, over, w)
    _, lim, s, over, w = best
    ctx.headers.update(_headers(lim, s, now))
    if not over:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(w / 1000)))
    return 429


def _headers(lim, s, now):
    return {
        "RateLimit-Limit": str(lim.capacity),
        "RateLimit-Remaining": str(s.remaining()),
        "RateLimit-Reset": str(s.reset(now)),
    }


def summary(st):
    if not st.limits:
        return {}
    return {"limited": dict(st.limited)}
